      "number_of_replicas": 0
    }
  }
}

PUT /fnscore-test-index/event/1
{"field":"value-1"}
PUT /fnscore-test-index/event/2
{"field":"value-2"}

POST /fnscore-test-index/event/_count
{
  "query": {
    "bool": {
      "must_not": [
        {
          "function_score": {
            "functions": [
              {
                "script_score": {
                  "script": "-1",
                  "lang": "expression"
                }
              }
